from cv import *
import cv as C
names2=names+['loge']
M2=np.hstack([M, np.log(M[:,[names.index('e')]]+1)])
C.names=names2; C.M=M2
def lad(Xtr,ytr,alpha,iters=50,w0=None):
    mu=Xtr.mean(0); sd=Xtr.std(0)+1e-9; Z=(Xtr-mu)/sd
    n,k=Z.shape; Za=np.hstack([np.ones((n,1)),Z])
    wt=np.ones(n) if w0 is None else w0
    R=alpha*np.eye(k+1); R[0,0]=0
    b=np.linalg.solve(Za.T@(Za*wt[:,None])+R,Za.T@(ytr*wt))
    for _ in range(iters):
        r=np.abs(ytr-Za@b); ww=wt/np.maximum(r,0.02)
        b=np.linalg.solve(Za.T@(Za*ww[:,None])+R*np.mean(ww),Za.T@(ytr*ww))
    return lambda Xt: np.hstack([np.ones((len(Xt),1)),(Xt-mu)/sd])@b, b
def cvl(cols,alpha):
    idx=[names2.index(c) for c in cols]; pm={};pa={}
    for p in set(g):
        tr=g!=p
        f,_=lad(M2[tr][:,idx],y[tr],alpha)
        te=(g==p)&dec
        if te.sum(): pm[p]=np.mean(np.abs(f(M2[te][:,idx])-y[te]))
        te=g==p; pa[p]=np.mean(np.abs(f(M2[te][:,idx])-y[te]))
    return round(np.mean(list(pm.values())),4), round(np.mean(list(pa.values())),4), pm
sets={'A':['e','loge'],'B2':['e','loge','bmi'],'B':['e','loge','mass'],'F':['e','loge','mass','wkg_last','sk_last','sk_mean','hr_mean','age','amb'],'Bs':['e','loge','mass','sk_mean']}
for nm,c in sets.items():
    for a in [1,10,50]:
        r=cvl(c,a); print(nm,a,r[:2])
r=cvl(['e','loge','bmi'],10); print({k:round(v,3) for k,v in r[2].items()})
E
