{"argv": ["bash","-c","cd /work; cat > gen_final.py <<'E'
import numpy as np, math, sys
from common import T
HALF=float(sys.argv[1]) if len(sys.argv)>1 else 0.5
SLOPE=float(sys.argv[2]) if len(sys.argv)>2 else 0.0
def lad_fit(X,y,alpha=10.0,iters=100):
    mu=X.mean(0); sd=X.std(0)+1e-9; Z=(X-mu)/sd; n,k=Z.shape
    Za=np.hstack([np.ones((n,1)),Z]); R=alpha*np.eye(k+1); R[0,0]=0
    b=np.linalg.solve(Za.T@Za+R,Za.T@y)
    for _ in range(iters):
        r=np.abs(y-Za@b); w=1/np.maximum(r,0.02)
        b=np.linalg.solve(Za.T@(Za*w[:,None])+R*np.mean(w),Za.T@(y*w))
    return dict(mu=mu.tolist(),sd=sd.tolist(),b0=float(b[0]),b=b[1:].tolist(),lo=X.min(0).tolist(),hi=X.max(0).tolist())
def build(h):
    Xs=[];ys=[]
    for pid,rows in T.items():
        for i in range(2,len(rows)-h):
            yy=rows[i+h]['core_temp']
            if yy is None: continue
            e=rows[i]['time_min']-rows[0]['time_min']
            Xs.append([e,math.log(e+1)]); ys.append(yy)
    return np.array(Xs),np.array(ys)
X15,y15=build(15)
X0,y0=build(0)
if len(sys.argv)>3: 
    X15=X15[X15[:,0]<=44]; y15=y15[:len(X15)]
P15=lad_fit(X15,y15); P0=lad_fit(X0,y0)
# restrict 15-min training to origins e<=44 handled by loop above (i<=44 since i+15<=59)
src='''"""Stateless 3A core-temperature forecaster (+15 min) with 3B fallback (current core).

Model: ridge-regularised least-absolute-deviation fit of core temperature on elapsed minutes
since the first history row (e, log(e+1)); relative time only, no absolute clock, no identity.
Other causal inputs (hr, skin, watts, anthropometrics, ambient) were tested in leave-one-person-out
CV and on dev but did not generalise, so they are not used. Interval: mean +/- half width
chosen from leave-one-person-out residuals (90%% target).
"""
import math

PARAMS_H15 = %r
PARAMS_H0 = %r
HALF_WIDTH = %r
HALF_SLOPE = %r


def _elapsed(history):
    try:
        return float(history[-1]['time_min'] - history[0]['time_min'])
    except Exception:
        return float(max(len(history) - 1, 0))


def _apply(p, e):
    vals = [e, math.log(e + 1.0)]
    out = p['b0']
    for v, m, s, b, lo, hi in zip(vals, p['mu'], p['sd'], p['b'], p['lo'], p['hi']):
        v = min(hi, max(lo, v))
        out += b * (v - m) / s
    return out


def predict(request):
    history = request.get('history') or []
    e = _elapsed(history) if history else 0.0
    e = max(e, 0.0)
    horizon = request.get('horizon_min', 15)
    if request.get('task') == '3B' or horizon == 0:
        p = PARAMS_H0
    else:
        p = PARAMS_H15
    mean = float(min(41.0, max(35.0, _apply(p, e))))
    half = HALF_WIDTH + HALF_SLOPE * min(e, 45.0)
    half = min(max(half, 0.05), 2.4)
    return {'mean': mean, 'lower': float(mean - half), 'upper': float(mean + half)}
'''
open('/work/submission.py','w').write(src%(P15,P0,HALF,SLOPE))
print(P15); print(P0)
